g=[[0]*8 for _ in range(8)]
for r in range(1,3):
    for c in range(3,5): g[r][c]=2
for r in range(5,7):
    for c in range(1,3): g[r][c]=2
# block def: (r1,c1) top-left of 2x2
blocks=[(1,3),(5,1)]
# cells: (pos, color, corner) corner in TL,TR,BL,BR relative to block
cells={
 (1,3):[((0,2),3,'TL'),((0,5),8,'TR'),((3,2),7,'BL'),((3,5),6,'BR')],
 (5,1):[((4,0),7,'TL'),((4,3),6,'TR'),((7,0),8,'BL'),((7,3),3,'BR')],
}
cw={'TL':'TR','TR':'BR','BR':'BL','BL':'TL'}
def corner_cell(b,corner):
    r1,c1=b
    return {'TL':(r1-1,c1-1),'TR':(r1-1,c1+2),'BL':(r1+2,c1-1),'BR':(r1+2,c1+2)}[corner]
def ray_dir(corner):
    return {'TL':(-1,-1),'TR':(-1,1),'BL':(1,-1),'BR':(1,1)}[corner]
for b,cs in cells.items():
    for (r,c),col,corner in cs:
        nc=cw[corner]
        rr,cc=corner_cell(b,nc)
        dr,dc=ray_dir(nc)
        while 0<=rr<8 and 0<=cc<8:
            g[rr][cc]=col
            rr+=dr; cc+=dc
for row in g: print(row)
